sp_widget.css:
.smart-parking-home {
  padding: 30px;
  max-width: 1100px;
  margin: 0 auto;
}

.hero {
  text-align: center;
  padding: 40px 20px;
}

.hero h1 {
  font-size: 42px;
  font-weight: 700;
  margin-bottom: 15px;
}

.hero p {
  font-size: 18px;
  margin-bottom: 25px;
}

.home-buttons {
  margin-top: 20px;
}

.home-buttons .btn {
  margin: 8px;
  padding: 12px 24px;
}

.parking-stats {
  margin-top: 25px;
}

.stat-card {
  background: #ffffff;
  padding: 30px;
  margin-bottom: 20px;
  text-align: center;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.10);
}

.stat-card h3 {
  margin-top: 0;
}

.stat-card h1 {
  font-size: 40px;
  font-weight: 700;
  margin-bottom: 0;
}

.active-booking {
  background: #ffffff;
  padding: 25px;
  margin-top: 25px;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.10);
}

.active-booking h2 {
  margin-top: 0;
}

.booking-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.booking-status {
  font-weight: 700;
}

@media (max-width: 767px) {

  .smart-parking-home {
    padding: 15px;
  }

  .hero {
    padding: 25px 10px;
  }

  .hero h1 {
    font-size: 32px;
  }

  .home-buttons .btn {
    display: block;
    width: 100%;
    margin: 10px 0;
  }

  .booking-heading {
    display: block;
  }

  .booking-heading .btn {
    margin-top: 10px;
  }
}

sp_widget.script:
(function() {

    data.availableSlots = 0;
    data.reservedSlots = 0;
    data.hasBooking = false;
    data.booking = null;


    // =====================================================
    // ROLE CHECKS
    // =====================================================

    // Admin Dashboard access
    data.isAdmin =
        gs.hasRole('x_1958892_smart_0.parking_admin') ||
        gs.hasRole('admin');


    // Security Verification access
    // Admin is also allowed to access Security page
    data.isSecurity =
        gs.hasRole('x_1958892_smart_0.parking_security') ||
        data.isAdmin;


    // =====================================================
    // AVAILABLE PARKING SLOTS
    // =====================================================

    var available = new GlideAggregate(
        'x_1958892_smart_0_parking_slot'
    );

    available.addQuery(
        'status',
        'available'
    );

    available.addAggregate('COUNT');
    available.query();

    if (available.next()) {

        data.availableSlots =
            parseInt(
                available.getAggregate('COUNT'),
                10
            ) || 0;
    }


    // =====================================================
    // RESERVED PARKING SLOTS
    // =====================================================

    var reserved = new GlideAggregate(
        'x_1958892_smart_0_parking_slot'
    );

    reserved.addQuery(
        'status',
        'reserved'
    );

    reserved.addAggregate('COUNT');
    reserved.query();

    if (reserved.next()) {

        data.reservedSlots =
            parseInt(
                reserved.getAggregate('COUNT'),
                10
            ) || 0;
    }


    // =====================================================
    // CURRENT USER ACTIVE BOOKING
    // =====================================================

    var booking = new GlideRecord(
        'x_1958892_smart_0_parking_booking'
    );

    booking.addQuery(
        'requested_by',
        gs.getUserID()
    );

    booking.addQuery(
        'booking_status',
        'IN',
        'confirmed,checked_in'
    );

    booking.orderByDesc(
        'sys_created_on'
    );

    booking.setLimit(1);

    booking.query();


    if (booking.next()) {

        data.hasBooking = true;

        data.booking = {

            sys_id:
                booking.getUniqueValue(),

            bookingNumber:
                booking.getDisplayValue(
                    'booking_number'
                ),

            parkingLocation:
                booking.getDisplayValue(
                    'parking_location'
                ),

            parkingSlot:
                booking.getDisplayValue(
                    'parking_slot'
                ),

            startTime:
                booking.getDisplayValue(
                    'start_time'
                ),

            endTime:
                booking.getDisplayValue(
                    'end_time'
                ),

            status:
                booking.getDisplayValue(
                    'booking_status'
                )
        };
    }

})();
